import os
from typing import Any, Dict, Optional

from openai import OpenAI

OPENAI_MODEL = "omni-moderation-latest"
DEFAULT_THRESHOLDS = {
    "violence": 0.7,
    "violence/graphic": 0.5,
    "hate": 0.7,
    "hate/threatening": 0.4,
    "harassment": 0.75,
    "harassment/threatening": 0.4,
    "self-harm": 0.5,
    "self-harm/intent": 0.4,
    "self-harm/instructions": 0.3,
    "sexual": 0.8,
    "sexual/minors": 0.01,
    "illicit": 0.5,
    "illicit/violent": 0.3,
}

_client: Optional[OpenAI] = None


def _get_client() -> OpenAI:
    global _client
    if _client is None:
        api_key = os.environ.get("OPENAI_API_KEY")
        if not api_key:
            raise RuntimeError("OPENAI_API_KEY is not set")
        _client = OpenAI(api_key=api_key)
    return _client


def _to_float(value: Any) -> Optional[float]:
    try:
        if value is None:
            return None
        return float(value)
    except (TypeError, ValueError):
        return None


def moderate_text(
    text: str,
    thresholds: Optional[Dict[str, float]] = None,
) -> Dict[str, Any]:
    if not isinstance(text, str) or not text.strip():
        raise ValueError("text must be a non-empty string")

    active_thresholds = dict(DEFAULT_THRESHOLDS)
    if thresholds:
        active_thresholds.update(thresholds)

    client = _get_client()
    response = client.moderations.create(
        model=OPENAI_MODEL,
        input=text,
    )

    result = response.results[0]
    category_scores = {}
    raw_scores = getattr(result, "category_scores", None)
    if raw_scores is not None:
        if hasattr(raw_scores, "model_dump"):
            category_scores = raw_scores.model_dump()
        elif isinstance(raw_scores, dict):
            category_scores = raw_scores
        else:
            category_scores = {
                key: getattr(raw_scores, key)
                for key in dir(raw_scores)
                if not key.startswith("_") and not callable(getattr(raw_scores, key))
            }

    exceeded = {}
    for category, threshold in active_thresholds.items():
        score = _to_float(category_scores.get(category))
        if score is not None and score >= threshold:
            exceeded[category] = {
                "score": score,
                "threshold": float(threshold),
            }

    allowed = len(exceeded) == 0

    return {
        "provider": "openai",
        "model": OPENAI_MODEL,
        "allowed": allowed,
        "blocked": not allowed,
        "category_scores": category_scores,
        "thresholds": active_thresholds,
        "exceeded_categories": exceeded,
    }
